<script setup lang="ts">import {ref} from 'vue';import * as reviews from '../api/reviews';import * as reports from '../api/reports';import * as runs from '../api/runs';import {download} from '../api/client';import {useResource} from '../hooks/useResource';import {refreshResources} from '../stores/resources';import {user} from '../stores/session';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import StatusBadge from '../components/common/StatusBadge.vue';const {data:rv,error}=useResource(reviews.list,[]),{data:rp}=useResource(reports.list,[]),{data:rr}=useResource(runs.list,[]);const runId=ref(sessionStorage.getItem('journey-selected-run')||'run-baseline'),comment=ref('已核验支持度去重、分组口径与编辑成本，请复核。'),message=ref('');async function submit(){try{await reviews.create({run_id:runId.value,comment:comment.value});refreshResources();message.value=''}catch(e:any){message.value=e.message}}async function decide(id:string,status:string){try{await reviews.decide(id,{status,comment:status==='approved'?'支持度与编辑对齐口径已核验，通过归档，保留描述性解释边界。':'请补充旅程分母及关联解释边界说明后重新提交。'});refreshResources();message.value=''}catch(e:any){message.value=e.message}}async function publish(id:string){try{const r=rv.value.find(x=>x.id===id)!;await reports.create({title:'栖山观展路径顺序策展图册',run_id:r.run_id,review_id:r.id});refreshResources();message.value=''}catch(e:any){message.value=e.message}}async function getReport(id:string){try{await download('/reports/'+id+'/download','栖山观展路径顺序.csv')}catch(e:any){message.value=e.message}}</script><template><PageTitle chapter="06" title="把路径依据，一起存档" description="分析员提交，策展复核人批准。下载包含模式支持度、代表序列与退出路径编辑对齐的CSV。"/><Notice :error="error||message"/><form v-if="user?.role!=='viewer'" class="paper form-grid" @submit.prevent="submit"><label>完成的运行<select v-model="runId" aria-label="完成的运行"><option v-for="r in rr.filter(x=>x.status==='completed')" :key="r.id" :value="r.id">{{r.id}}</option></select></label><label>策展备注<textarea v-model="comment"/></label><button class="primary">提交路径复核</button></form><section class="paper"><h2>复核记录</h2><article v-for="r in rv" :key="r.id" class="review-row"><StatusBadge :status="r.status"/><div><b>{{r.run_id}}</b><p>{{r.comment}}</p><small>{{r.reviewer||'等待策展复核'}}</small></div><div class="actions"><template v-if="user?.role==='admin'&&r.status==='pending'"><button @click="decide(r.id,'approved')">批准方案</button><button @click="decide(r.id,'rejected')">退回复查</button></template><button v-if="user?.role!=='viewer'&&r.status==='approved'" @click="publish(r.id)">生成归档报告</button></div></article></section><section class="paper"><h2>可下载图册</h2><article v-for="r in rp" :key="r.id" class="record report-row"><div><b>{{r.title}}</b><small>{{r.run_id}}</small></div><button @click="getReport(r.id)">下载顺序 CSV ↓</button></article></section></template>
